CREATE TABLE invoices (id VARCHAR(36) PRIMARY KEY, operation_id VARCHAR(120) NOT NULL UNIQUE, customer_id VARCHAR(120) NOT NULL, subtotal NUMERIC(14,2) NOT NULL, tax NUMERIC(14,2) NOT NULL, total NUMERIC(14,2) NOT NULL, status VARCHAR(30) NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE TABLE invoice_lines (id BIGSERIAL PRIMARY KEY, invoice_id VARCHAR(36) NOT NULL REFERENCES invoices(id), description VARCHAR(300) NOT NULL, quantity INTEGER NOT NULL CHECK(quantity > 0), unit_price NUMERIC(14,2) NOT NULL);